function buildPostmortem(f){
  f=f||{};
  var title=String(f.title||'未命名事故').trim()||'未命名事故';
  var impact=String(f.impact||'').trim()||'（待补充）';
  var timeline=String(f.timeline||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var root=String(f.root||'').trim()||'（待补充）';
  var actions=String(f.actions||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;});
  var lines=['# 事故复盘（Postmortem）','', '## 概要','- 事故：'+title, '- 影响：'+impact, ''];
  lines.push('## 时间线');
  if(timeline.length) timeline.forEach(function(t){ lines.push('- '+t); }); else lines.push('- （待补充）');
  lines.push('','## 根因分析',''+root,'');
  lines.push('## 改进项（Action Items）');
  if(actions.length) actions.forEach(function(a,i){ lines.push((i+1)+'. [ ] '+a); }); else lines.push('- [ ] （待补充）');
  return {title:title, markdown:lines.join('\n'), actionCount:actions.length, timelineCount:timeline.length};
}
var EXPORTS={buildPostmortem:buildPostmortem};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PostmortemForgePure = EXPORTS; }
